-- mod-temucraft-lostlands: map_dbc rows for our maps (800-822, from the client's Map.dbc). The server's Map.dbc is stock,
-- so without them these maps don't exist server side (and their instance resets crash the worldserver).
DELETE FROM `map_dbc` WHERE `ID` IN (803,804,805,800,801,802,806,807,808,809,813,814,815,817,816,818,819,820,821,822);
